<?php elseif($page==='import'&&$user['role']==='admin'):?><h1>Import Historical Substitutions</h1><?php require __DIR__.'/import-status.php';?><section class="card"><p>Upload a CSV or XLSX using the template headers. Add staff to the Teaching Staff directory first, individually or using bulk upload. No staff login account is required. Use text dates in YYYY-MM-DD format. Additional columns, including old class dates and approval remarks, are preserved with the record.</p><p>Historical records do not restart approvals or send email. Only newly submitted applications use structured class sessions.</p><a href="?page=teaching">Manage / bulk upload teaching staff</a> · <a href="?page=template">↓ Download import template</a><form method="post" enctype="multipart/form-data"><?php csrf();?><input type="hidden" name="action" value="import_preview"><?php field('sheet','CSV or XLSX file','file');?><button>Step 1: Validate and preview</button></form></section><?php if(isset($_SESSION['import'])):?><section class="card"><h2><?=count($_SESSION['import'])?> new records ready</h2><p>These are preview rows only. They will not appear in reports until you save them below. Duplicates are skipped.</p><?php if($_SESSION['import']):?><form method="post"><?php csrf();?><input type="hidden" name="action" value="import_commit"><button>Step 2: Save these records to database</button></form><?php endif;?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Travel dates</th><th>Status</th></tr></thead><tbody><?php foreach($_SESSION['import']as $item):$r=$item['row'];?><tr><td><?=e($r['Name'])?></td><td><?=e($r['Travel Start Date'].' to '.$r['Travel End Date'])?></td><td><?=e($r['Status'])?></td></tr><?php endforeach;?></tbody></table></div><form method="post"><?php csrf();?><input type="hidden" name="action" value="import_commit"><button <?=empty($_SESSION['import'])?'disabled':''?>>Save these records to database</button></form></section><?php endif;?>
<?php elseif($page==='edit_user'&&$user['role']==='admin'):$edit=one('SELECT * FROM users WHERE id=?',[(int)($_GET['id']??0)]);if($edit):?><h1>Edit Account</h1><section class="card"><form method="post"><?php csrf();?><input type="hidden" name="action" value="edit_user"><input type="hidden" name="id" value="<?=$edit['id']?>"><div class="form-grid"><label>Full name<input name="name" required value="<?=e($edit['name'])?>"></label><label>Email<input name="email" type="email" required value="<?=e($edit['email'])?>"></label><label>Role<select name="role"><?php foreach(accountRoles()as $role):?><option value="<?=e($role)?>" <?=$edit['role']===$role?'selected':''?>><?=e($role==='exam'?'Examination & Student Records (exam)':$role)?></option><?php endforeach;?></select></label><label>Department<select name="department"><option value="">Not assigned</option><?php foreach(accountDepartments()as $dept):?><option <?=$edit['department']===$dept?'selected':''?>><?=e($dept)?></option><?php endforeach;?></select></label><?php if(staffMetadataReady()){$profile=staffProfile((int)$edit['id']);?><label>Staff type<select name="staff_type"><?php foreach(['Regular','Adjunct']as $type):?><option <?=$profile['staff_type']===$type?'selected':''?>><?=e($type)?></option><?php endforeach;?></select></label><label>Status reason (optional)<input name="status_reason" maxlength="1000" value="<?=e($profile['status_reason'])?>"></label><?php }field('reset_password','Official login password (required when promoting faculty; otherwise optional, 12+ characters)','password',[],false);if(attReady()):?><label class="check"><input type="checkbox" name="teaching_enabled" value="1" <?=one('SELECT user_id FROM tutor_permissions WHERE user_id=? AND enabled=1',[$edit['id']])?'checked':''?>>Teaching attendance enabled (independent of official role)</label><?php endif;?><label class="check"><input type="checkbox" name="active" value="1" <?=$edit['active']?'checked':''?>>Active (uncheck to make Inactive)</label></div><button>Save account</button></form></section><?php endif;?>
<?php elseif($page==='account'):?><h1>My Account</h1><section class="card"><p><?=e($user['name'].' · '.$user['email'])?></p><form method="post"><?php csrf();?><input type="hidden" name="action" value="password"><?php field('current_password','Current password','password');field('new_password','New password (at least 12 characters)','password');?><button>Change password</button></form></section>
<?php else:?><div class="notice error">This page is not available to your account.</div><?php endif;?>
